import type { Creature, CreatureAttribute, FormStage } from "@/types/creature";

const LIST_SOURCE = "https://wiki.biligame.com/rocom/%E7%B2%BE%E7%81%B5%E5%9B%BE%E9%89%B4";
const DIMO_SOURCE = "https://wiki.biligame.com/rocom/%E8%BF%AA%E8%8E%AB";
const UPDATED_AT = "2026-04-05";
const BWIKI_LICENSE_NOTE = "BWiki 文字与数据内容标注为 CC BY-NC-SA 4.0；图片权利状态仍需逐张人工确认，MVP 不下载、不热链。";

type SeedEntry = {
  id: string;
  name: string;
  attributes: CreatureAttribute[];
  stage: FormStage;
  forms?: string[];
  sourceUrl?: string;
  captureLocations?: string[];
  obtainMethods?: string[];
  evolutionMethods?: string[];
  isCatchable?: Creature["isCatchable"];
  isEventLimited?: Creature["isEventLimited"];
  availabilityStatus?: Creature["availabilityStatus"];
  description?: string;
  skills?: Creature["skills"];
  confidence?: Creature["confidence"];
  updatedAt?: string;
};

const imageNote =
  "MVP 使用本地占位图；BWiki 列表页存在该精灵立绘，原图版权与本地化使用需人工确认后再替换。";

const wikiPageUrl = (title: string) => `https://wiki.biligame.com/rocom/${encodeURIComponent(title)}`;

const imageFilePageUrl = (creatureName: string, formName: string) => {
  const fileName =
    formName === creatureName
      ? `文件:页面 宠物 立绘 ${creatureName} 1.png`
      : `文件:页面 宠物 立绘 ${creatureName}（${formName}） 1.png`;
  return wikiPageUrl(fileName);
};

const formImage = (id: string, formIndex: number): { path: string; status: "local" | "placeholder" } => {
  const pngPath = `/images/creatures/${id}-${String(formIndex + 1).padStart(2, "0")}.png`;
  return { path: pngPath, status: "local" };
};

const createCreature = (entry: SeedEntry): Creature => {
  const sourceUrl = entry.sourceUrl ?? wikiPageUrl(entry.name);
  const pending = "待确认";

  return {
    id: entry.id,
    name: entry.name,
    attributes: entry.attributes,
    forms: (entry.forms ?? [entry.name]).map((formName, index) => {
      const img = formImage(entry.id, index);
      return {
        formId: `${entry.id}-${String(index + 1).padStart(2, "0")}`,
        name: formName,
        stage: entry.stage,
        image: img.path,
        sourceUrl,
        imageSourceUrl: imageFilePageUrl(entry.name, formName),
        imageLicenseNote: BWIKI_LICENSE_NOTE,
        imageReviewStatus: "needs-review",
        imageStatus: img.status,
        sourceNote: img.status === "placeholder"
          ? "MVP 使用统一占位图；BWiki 列表页存在该精灵立绘，版权与本地化使用需人工确认。"
          : `${imageNote} 当前文件为本地缓存，来源文件页已记录。`,
      };
    }),
    obtainMethods: entry.obtainMethods ?? [pending],
    captureLocations: entry.captureLocations ?? [pending],
    evolutionMethods: entry.evolutionMethods ?? [pending],
    isCatchable: entry.isCatchable ?? "unknown",
    isEventLimited: entry.isEventLimited ?? "unknown",
    availabilityStatus: entry.availabilityStatus ?? "unknown",
    skills: entry.skills ?? [
      {
        name: pending,
        description: "技能列表尚未逐条核验。",
        confidence: "unknown",
      },
    ],
    description: entry.description ?? "简介待确认。当前仅确认图鉴编号、名称、属性与形态信息。",
    sources: [
      {
        title: "洛克王国:手游WIKI_BWIKI 精灵图鉴",
        url: LIST_SOURCE,
        kind: "dex-list",
        note: "用于确认图鉴编号、名称、属性、形态与公开立绘条目。",
      },
      {
        title: `${entry.name} - 洛克王国:手游WIKI_BWIKI`,
        url: sourceUrl,
        kind: "creature-page",
        note: "用于补充单条目详情；未逐条核验的字段仍保留为“待确认”。",
      },
    ],
    updatedAt: entry.updatedAt ?? UPDATED_AT,
    confidence: entry.confidence ?? "partial",
    sourceNote:
      "编号、名称、属性和形态来自 BWiki 图鉴列表；未核验字段显式保留为“待确认”。",
  };
};

